    function testRegression_property() public {
        address alice = address(0x123);
        address bob = address(0x456);
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.deposit{value: 1 ether}();
        vm.prank(address(this));
        c.migrateTo(bob);
        assertEq(address(c).balance, 0);
    }
}
